package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.IOContext;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.GeneratorBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.dataformat.xml.XmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator;
import com.fasterxml.jackson.dataformat.xml.util.DefaultXmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.StaxUtil;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import javax.xml.namespace.QName;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamWriter;
import org.codehaus.stax2.XMLStreamWriter2;
import org.codehaus.stax2.ri.Stax2WriterAdapter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class ToXmlGenerator_writeBoolean_TriageGen2Test {

    @Mock
    private IOContext ioContext;
    @Mock
    private ObjectCodec codec;
    @Mock
    private XMLStreamWriter xmlStreamWriter;
    @Mock
    private PrettyPrinter prettyPrinter;

    private ToXmlGenerator generator;
    private final QName testQName = new QName("http://test.com", "testElement");

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // Constructor: public ToXmlGenerator(IOContext ctxt, int stdFeatures, int xmlFeatures, ObjectCodec codec, XMLStreamWriter sw);
        generator = new ToXmlGenerator(ioContext, 0, 0, codec, xmlStreamWriter);
    }

    /**
     * Test Case 1: Test when _nextName is null. 
     * This triggers handleMissingName(). 
     * Note: handleMissingName() usually throws an exception in Jackson, 
     * so we expect an exception here.
     */
    @Test(expected = RuntimeException.class)
    public void testWriteBoolean_MissingName() throws Exception {
        generator.writeBoolean(true);
    }

    /**
     * Test Case 2: Test when _nextIsAttribute is true.
     * Should call _xmlWriter.writeBooleanAttribute.
     */
    @Test
    public void testWriteBoolean_AsAttribute() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(true);

        generator.writeBoolean(true);

        verify(xmlStreamWriter).writeBooleanAttribute(
                isNull(), 
                eq(testQName.getNamespaceURI()), 
                eq(testQName.getLocalPart()), 
                eq(true)
        );
    }

    /**
     * Test Case 3: Test when checkNextIsUnwrapped() is true.
     * Should call _xmlWriter.writeBoolean directly.
     */
    @Test
    public void testWriteBoolean_Unwrapped() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextIsUnwrapped(true);

        generator.writeBoolean(false);

        verify(xmlStreamWriter).writeBoolean(false);
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Test Case 4: Test when _xmlPrettyPrinter is NOT null.
     * Should call _xmlPrettyPrinter.writeLeafElement.
     */
    @Test
    public void testWriteBoolean_WithPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextIsUnwrapped(false);
        generator.setPrettyPrinter(prettyPrinter);

        generator.writeBoolean(true);

        verify(prettyPrinter).writeLeafElement(
                eq(xmlStreamWriter),
                eq(testQName.getNamespaceURI()),
                eq(testQName.getLocalPart()),
                eq(true)
        );
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Test Case 5: Test when _xmlPrettyPrinter is null (Default behavior).
     * Should call writeStartElement, writeBoolean, and writeEndElement.
     */
    @Test
    public void testWriteBoolean_DefaultNoPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextIsUnwrapped(false);
        // Ensure pretty printer is null

        generator.writeBoolean(true);

        verify(xmlStreamWriter).writeStartElement(testQName.getNamespaceURI(), testQName.getLocalPart());
        verify(xmlStreamWriter).writeBoolean(true);
        verify(xmlStreamWriter).writeEndElement();
    }

    /**
     * Test Case 6: Test XMLStreamException handling.
     * Should catch XMLStreamException and wrap it via StaxUtil.throwAsGenerationException.
     * Since StaxUtil is static, we expect the exception to propagate.
     */
    @Test(expected = Exception.class) 
    public void testWriteBoolean_ThrowsXMLStreamException() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextIsUnwrapped(true);

        // Force an exception from the underlying writer
        doThrow(new XMLStreamException("Simulated Error")).when(xmlStreamWriter).writeBoolean(anyBoolean());

        generator.writeBoolean(true);
    }
}
